  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'Бу тарҕатыыга PlayHub сайт администратора официальнай сибээс аадырыһын, төлөбүрдээх сибээс ханаалларын уонна тас өйөбүл ханаалларын настройкалыахтаах. Бу сирэй бэрэбиэркэлэммэтэх электроннай почта аадырыһын соруйан көрдөрбөт.',
  'On this page' => 'Бу сирэйгэ',
  'Open Help Center' => 'Көмө киинин арый',
  'Open settings' => 'Настройкалары арый',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'Настройкалары арыйан баран, Куттал суох буолуутугар киирэн баран, паролу эбэтэр икки фактордаах диалогу туттуҥ. Икки фактордаах тиэрдии настройкаламмыт түгэнигэр электроннай почтаны эбэтэр төлөпүөнү өйүүр.',
  'Operational snapshot' => 'Оперативнай снимок',
  'Optional, but recommended' => 'Баҕар, ол гынан баран сүбэлииллэр',
  'Other' => 'Другое',
  'Partnerships, press, and platform operations.' => 'Партнерстволар, бэчээт уонна платформа дьайыылара.',
  'Payment help' => 'Төлөбүр көмөтө',
  'Platform' => 'Платформа',
  'Playback' => 'Оонньуу',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Оонньуу хаамыыта, кэлин көрүү туруга, сөбүлээһиннэр, комментарийдар, сурутуулар, биллэриилэр уонна админ анаалыстара аутентификацияламмыт платформа функцияларыгар ситимнээх буоллахтарына, базаҕа хараллаллар.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Сүрүн навигация уонна аккаунт менютунан оонньотуу, комментарийдар, сөбүлээһиннэр, кэлин көрүү, сурутуулар, биллэриилэр, суруктар, плейлисттар уонна тыл настройкалара бааллар.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub диэн биир аккаунтан айааччы ис хоһоонун ыытар, көрөр, былаанныыр, салайар уонна салайар видео платформа.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub диэн бу тарҕатыыга үлэлиир видеоплатформа, айааччыларга, көрөөччүлэргэ, уопсастыбаларга уонна платформа оператордарыгар анаан оҥоһуллубут.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub биир платформаттан оҥорооччу ханаалларын, видео ыытыыларын, былааннаммыт бэчээттээһини, сурутуулары, комментарийдары, плейлисттары, кэлин көрүү, быһа эфирдээх ис хоһоон страницаларын уонна салайыы инструменнарын биэрэр.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub логин сеанстарыгар, API аутентификациятыгар, CSRF/куттал суох буолуутун быһыытыгар, тылы талыыга, тиэмэни талыыга, аккаунт менютун туругар уонна приложение үлэлииригэр ирдэнэр атын функцияларга наадалаах кукилары уонна браузер хранилищетын туһанар.',
  'playhub_language, theme' => 'playhub_тыл, тиэмэ',
  'Popular questions' => 'Биһирэмнээх ыйытыылар',
  'Preference storage' => 'Баҕарыллыбыт харайыы',
  'Privacy Policy' => 'Конфиденциальность политиката',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'Конфиденциальность, куки, аккаунт харыстабыла, өйөбүл суруктара уонна модерация даннайдара PlayHub-ка холбоммут политикалар уонна бэкэнд-регистрациялар көмөлөрүнэн дьаһаналлар.',
  'Profile, login, security, and settings help.' => 'Профиль, логин, куттал суох буолуута уонна настройкалар көмөлөһөллөр.',
