  'Search help articles, topics, or questions...' => 'Көмөлөһөр ыстатыйалары, тиэмэлэри эбэтэр ыйытыылары көрдөө...',
  'Select a reason' => 'Биричиинэни талыҥ',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Биир эбэтэр хас да видеофайлы талыҥ, ирдэнэр сиһилии киллэриҥ, категорияны уонна тылы талыҥ, уруһуйу эбэн биэриҥ, көстөрүн талыҥ уонна бэчээттээҥ. Улахан билэлэр сервер үлэтин саҕалыан иннинэ чааһынан ыытыллаллар.',
  'Send a message and it will be saved for admins.' => 'Сообщение ыыт уонна админнарга хараллан хаалыа.',
  'Send billing details to admin support for review.' => 'Бэрэбиэркэлииргэ төлөбүр сиһилиитин администратор өйөбүлүгэр ыытыҥ.',
