  'Service operation' => 'Сервис үлэтэ',
  'session, token' => 'сессия, токен',
  'Settings and login' => 'Настройкалар уонна киирии',
  'Short summary' => 'Кылгас түмүгэ',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Киирэн баран, аккаунт, профил, пароль, биллэрии, конфиденциальность уонна айааччы баҕа санааларын Настройкаларын туһан. Айааччы ыытыытын уонна ис хоһоонун боппуруостарыгар видео аата, ханаала, браузера уонна ыытыы страницатыгар көстөр ханнык баҕарар алҕас оҥоһуллуохтаах.',
  'Sign in for account support' => 'Аккаунт өйөбүлүгэр киир',
  'Signed in' => 'Киирбит',
  'Start uploading' => 'Саҕалыыр',
  'Still can’t find an answer?' => 'Билигин да эппиэти булбаккын дуо?',
  'Stored for admins' => 'Админнарга харалла сытар',
  'Stores language, theme, and interface preferences.' => 'Тылы, тиэмэни уонна интерфейс сөбүлээһиннэрин харайар.',
  'Studio, playlists, analytics, channels.' => 'Студия, плейлисты, аналитика, каналы.',
  'Submit a billing or refund message to admin support.' => 'Админ өйөбүлүгэр төлөбүр эбэтэр харчы төннөрүү туһунан сурук ыытыҥ.',
  'Submit refund request' => 'Төннөрүү көрдөһүүтүн ыыт',
  'Submit request' => 'Ыйытыы ыыт',
  'Subscription cancellation' => 'Сурутууну тохтотуу',
  'Support dashboard' => 'Өйөбүл панелыгар',
  'System status' => 'Систиэмэ туруга',
  'Table' => 'Таблица',
  'Taxonomies' => 'Таксономиялар',
  'Technical issue' => 'Техническэй боппуруос',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Билиҥҥи PlayHub API-ны кытта интеграцияларга уонна тиэйии үлэтин хаамыытыгар техническэй бэлиэтээһиннэр.',
  'Tell us more about your question or request...' => 'Ыйытыыҥ эбэтэр көрдөһүүҥ туһунан сиһилии кэпсээ...',
  'Terms of Use' => 'Туһаныы усулуобуйата',
  'The configured' => 'Настройкаламмыт',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Разработчик страницата Laravel бэкэндигэр холбонор: маршрут инвентаризацията, база ахсаана, тиэйии кээмэйэ уонна платформа метаданнайдара /api/developers-тан ылыллыбыттар.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Фронтенд талыллыбыт тылы, тиэмэни, оонньотуу уочаратын, көрүү хаамыытын уонна интерфейс туругун курдук сөбүлээһиннэри харайар, онон страница навигациятыгар уонна хаттаан тиэйиигэ опыт биир тэҥ буолар.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Обработка үлэтэ оҥоһуулары кодтыыр, наада буоллаҕына эскизтары оҥорор, тиэкистэри харайар уонна обработка бүппүтүн кэннэ видеолары бэлэм диэн бэлиэтиир. Кэлэр былааннаммыт видеолар былаанньыт таһаарыар диэри туспа буолаллар.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Ыытыы систиэмэтэ базаҕа олоҕурар, API-тан категориялары уонна тыллары өйүүр, ыытыллыбыт видеолары оҥорор, уруһуйдары уонна тиэкистэри харайар, уонна былааннаммыт ис хоһоону тахсыар диэри туспа тутар.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Бу сирэйгэ PlayHub сеанстарга, куттал суох буолуутугар, сөбүлээһиннэргэ, оонньотууга уонна бэрэбиэркэлэммит функцияларга кукилары уонна браузер хранилищетын хайдах туһанарын быһаарар.',
  'Ticket source' => 'Билиэт источнига',
  'Top content categories' => 'Ис хоһоон бастыҥ категориялара',
  'Topic' => 'Тиэмэ',
  'Transaction / invoice' => 'Транзакция / накладной',
  'Transaction / invoice ID' => 'Транзакция / счет-фактура идентификатора',
  'Unable to send message.' => 'Сурук ыытар кыаллыбат.',
  'Unable to submit refund request.' => 'Төннөрүү сайабылыанньатын ыытар кыах суох.',
  'Understanding admin support tickets' => 'Админ өйөбүлүн билиэттэрин өйдөөһүн',
  'Upload and processing help' => 'Ыытыы уонна оҥоруу көмөтө',
  'Upload chunks' => 'Чаастары ыыт',
  'Upload issues' => 'Ыытыыга кыһалҕалар',
  'Upload languages' => 'Тыллары ыытыы',
  'Upload limit' => 'Ыытар лимит',
  'Upload options' => 'Ыытыы варианнара',
  'Upload or processing' => 'Ыытыы эбэтэр оҥоруу',
  'Upload page' => 'Страницаны ыыт',
  'Upload pipeline' => 'Ыытар турба',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'PlayHub быһа эфирдээх даннайдарынан ыыт, көр, суруттар, дьаһай уонна оҥор.',
  'Uploaded videos' => 'Ыытыллыбыт видеолар',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Ыытыллыбыт видеолар оонньонор варианнарга кодировкаланаллар. Үлэ бириэмэтэ билэ кээмэйиттэн, болдьоҕуттан, сервер нагрузкатыттан уонна уочарат туругуттан тутулуктаах. Загрузка страницата уонна Creator Studio видеозаписьтан дьиҥнээх обработка туругун көрдөрөллөр.',
  'Uploads, scheduling, and processing are available.' => 'Ыытыылар, былааннааһын уонна оҥоруу бааллар.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Айааччы үлэтин хаамыыларыгар /api/videos, ханаал түмүктэрин уонна аутентификацияламмыт маршруттары туһаныҥ.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Видеоларга уонна комментарийдарга анаан оҥоһуллубут отчуот дьайыыларын туһан, оччоҕо админнар чопчу ис хоһоонноох ыйыыны ылыахтара. Администратор панелларын страницалара туһанааччыларга, ис хоһооҥҥо, отчуоттарга, харчы оҥорууга, анаалыска, өйөбүлгэ, оруолларга уонна систиэмэ настройкаларыгар анаан тыыннаах база даннайдарын туһаналлар.',
  'Use Contact Us' => 'Биһигини кытта сибээстэһиҥ',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Үгэс буолбут API ыйытыыларыгар JSON уонна файллары ыытыыга FormData туттуҥ. Бэрэбиэркэлээһини туораамаҥ: категориялар уонна тыллар база идентификатордара буолаллар, көстүү уопсай, ааҕыллыбатах эбэтэр чааһынай эрэ буолар, уонна тиэкистэр SRT, VTT эбэтэр TXT билэлэри ылыналлар.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Настройкалары туһанан профилгын, куттал суох буолуутун, паролгун, икки фактордаах тиэрдиини, тэриллэри, сөбүлээһиннэри уонна биллэрии варианнарын саҥардыҥ. Аккауҥҥар киирэр кыах суох буоллаҕына, киирии ньыматын туһан уонна аккаунт электроннай почтатын сайт администраторыгар биэр.',
  'Use the contact form' => 'Сибээс форматын туһаныҥ',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Видеоларга, комментарийдарга уонна уопсастыба суруйууларыгар отчуот дьайыыларын туһан, оччоҕо админнар чопчу ис хоһоонноох ыйыыны ылыахтара.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Ис хоһоон платформа быраабылаларын кэһиэн сөп буоллаҕына, видеоларга, комментарийдарга уонна уопсастыбаннай суруйууларга отчуот дьайыыларын туһаныҥ. Бу отчуоттар дьиҥнээх ис хоһоонноох бэлиэтээһиҥҥэ ситимнээхтэр уонна уопсай суруктан ордуктар, тоҕо диэтэххэ администратордар чопчу пууну көрүөхтэрин сөп.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Аккаунт көмөтүгэр, ис хоһоон отчуоттарыгар, техническэй боппуруостарга уонна администратор көрдөһүүтүгэр сөптөөх PlayHub ханаалы туһаныҥ.',
  'Video categories' => 'Видео категориялара',
  'Video for everyone. Built for creators and viewers.' => 'Барыларыгар анаан видео. Дьиҥнээх платформа даннайдарыттан тутуллубут.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Видеону ыытыы, былааннааһын, уруһуйдар уонна оҥоруу кыһалҕалара.',
  'Videos, thumbnails, captions, processing.' => 'Видеолар, уруһуйдар, тиэкистэр, оҥоһуу.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Көрөөччүлэр категориялары көрүөхтэрин, видеолары көрүөхтэрин, ис хоһоону көрүөхтэрин, ханаалларга суруттарыахтарын, кэлин көрөргө видеолары харыстыахтарын, комментарий биэриэхтэрин, биллэриилэри ылыахтарын, тыл уонна доступность сөбүлээһиннэрин салайан биэриэхтэрин сөп.',
  'Viewing and community help' => 'Көрүү уонна уопсастыба көмөтө',
  'Waiting for backend endpoint inventory.' => 'Бэкэнд түмүк точкаларын инвентаризациятын кэтэһэбит.',
  'We’re here to help.' => 'Биһиги көмөлөһө кэллибит.',
  'What is PlayHub?' => 'PlayHub диэн тугуй?',
  'What PlayHub does' => 'PlayHub тугу гынар',
  'Where do contact messages go?' => 'Контакт суруктара ханна баралларый?',
  'Why is my video still processing?' => 'Тоҕо мин видеом өссө да оҥоһулларый?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Ээх. Загрузка страницатыгар төрүт былаан күнүн уонна бириэмэтин эйгэтин туһаныҥ. Бэкэнд scheduled_at диэни харайар, видеоны оҥорор, күнэ кэлэр кэмигэр туспа туттар уонна Laravel былааннааччыта былааннаммыт бириэмэ кэнниттэн үлэлээтэҕинэ таһаарар.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Ээх. Загрузкаҕа төрүт расписание эйгэтин туттуҥ. Бэкэнд scheduled_at диэни харайар уонна былаан бириэмэтэ тиийдэҕинэ видеоны таһаарар.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Эн ыалдьыт быһыытынан көрөҕүн. Аккауҥҥа аналлаах инструменнарга киирэргэ киир.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Эһиги аккааҥҥыт учуотун, профиль дьайыытын, ыытыллыбыт ис хоһоону, комментарийдары, суруктары уонна аккааҥҥыттан оҥоһуллубут ханнык баҕарар оҥорооччу эбэтэр дьаһайааччы дьайыыларын иһин эппиэтинэстээххит. Күүстээх пароллары туттуҥ уонна икки фактордаах тиэрдии ньымаларын аныгы тутуҥ.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Браузер кукиларын уонна локальнай хранилищены браузер настройкаларыгар ыраастыаххын сөп. Суолталаах хранилищены ыраастыыр ​​буоллаххына, эйигин тахсыаххын, тыл/тиэмэ сөбүлээһиннэрин сброс оҥоруоххун сөп, олохтоох оонньооһун туругун суох оҥоруоххун сөп уонна эйигиттэн хаттаан киирэргин ирдиэххин сөп.',
  'You receive a response by email.' => 'Эһиги электроннай почтанан хоруйу ылаҕыт.',
  'You’re in control' => 'Эн хонтуруоллуур буолаҕын',
  'Your choices' => 'Эн талыыларгын',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Эн суруккун саайт бэкэндигэр быһаччы харайаллар уонна өйөбүл анныгар администратор панелыгар көстөр.',
