  'Upload your first video and give viewers a clear reason to subscribe.' => 'Бастакы видеоҕун ук уонна көрөөччүлэргэ суруттарарга чуолкай төрүөтү биэр.',
  'Use Shorts for discovery' => 'Арыйыыга шортиктары туттуҥ',
  'Keep testing quick hooks and link viewers to longer videos.' => 'Түргэнник тардыылары бэрэбиэркэлээ уонна көрөөччүлэри уһун видеоларга ситимнээ.',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'Ханаалгын була илик көрөөччүлэргэ тиийэргэ кылгас вертикальнай видеолары оҥор.',
