  'Reply to recent comments and turn viewers into returning fans.' => 'Кэлиҥҥи комментарийдарга хоруйдаа уонна көрөөччүлэри төннөр фанаттарыгар кубулут.',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'Кэлэр ыытыыга ыйытыы биэр уонна комментарийдар кэллэхтэринэ түргэнник хоруйдаа.',
  'View comments' => 'Комментарийдары көр',
  'Improve public reach' => 'Дьон-сэргэ тиийиитин тупсарыы',
  'Keep strong videos visible and refresh weak titles.' => 'Күүстээх видеолары көстөр гына оҥор уонна мөлтөх ааттары саҥардан биэр.',
  'Explore tools' => 'Инструменнары чинчийии',
  'Open the right workflow fast' => 'Сөптөөх үлэ хаамыытын түргэнник арый',
  'Upload planner' => 'Ыытыы былааннааччыта',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'Ааттардаах, бэлиэлэрдээх, көстүүлээх уонна кыра уруһуй хардыыларынан саҥа ыытыыны саҕалаа.',
  'Shorts studio' => 'Кылгастык устуудьуйа',
  'Create short videos for faster discovery and mobile viewers.' => 'Түргэнник арыйарга уонна мобильнай көрөөччүлэргэ кылгас видеолары оҥор.',
  'Content manager' => 'Контент-менеджер',
  'Review visibility, monetization, comments, and performance in one place.' => 'Көрүҥү, харчыны оҥорууну, комментарийдары уонна үлэни биир сиргэ көрүҥ.',
  'Analytics review' => 'Аналитика ырытыыта',
  'Track views, likes, comments, publishing status, and trends.' => 'Көрүүлэри, сөбүлээһиннэри, комментарийдары, бэчээттээһин туругун уонна хайысхалары көрүҥ.',
  'Channel profile' => 'Ханаал профила',
  'Update your bio, channel details, and public creator presence.' => 'Биографияҕын, ханаалгын сиһилии уонна уопсастыбаннай айааччы баар буолуутун саҥардан биэр.',
  'Audience building' => 'Көрөөччүнү тэрийии',
  'Study subscribers, comments, and what viewers respond to most.' => 'Суруттарбыт дьону, комментарийдары уонна көрөөччүлэр туохха ордук эппиэттииллэрин үөрэт.',
  'Top content to learn from' => 'Үөрэнэргэ бастыҥ ис хоһоон',
  'Upload videos to unlock performance lessons.' => 'Толоруу уруоктарын арыйарга видеолары ыыт.',
