  'Upload source' => 'Источник ыытыы',
  'Choose a local video file or import a public video from an enabled provider.' => 'Олохтоох видеофайлы талыҥ эбэтэр көҥүллэммит провайдертан уопсастыбаннай видеоны киллэриҥ.',
